// ── QR Code widget ───────────────────────────────────────────────────────────
// Renders a placeholder container here; the actual QR image is generated by the
// qrcodejs library into that container in a post-render pass (see renderQRCodes()
// below), since it draws directly into the DOM rather than returning a string.
function qrContentFor(w) {
  if (w.qrPreset === 'wifi') {
    if (!w.qrSSID) return '';
    // Standard "WIFI:" QR format — recognized natively by iOS/Android camera apps
    // to offer a one-tap "Join Network" action.
    const esc = (s) => String(s || '').replace(/([\\;,:"])/g, '\\$1');
    return `WIFI:T:${w.qrEncryption || 'WPA'};S:${esc(w.qrSSID)};P:${esc(w.qrPassword || '')};;`;
  }
  return (w.qrContent || '').trim();
}
// ── Web Page widget ──────────────────────────────────────────────────────────────────────────────────────────────
// Shows a page the household hosts (or any simple page that allows being framed) inside the layout. The frame is
// sandboxed with only allow-scripts: the page can run its own code, but it gets an opaque origin, so it cannot read
// this app's cookies, storage or settings or call its API. Many big sites (Canvas, most school portals) refuse to be
// framed and need a sign-in; those show the browser's own "refused to connect" inside the box, which is expected.
const webPageTimers = new Map();   // widget id -> refresh interval
// Only plain web addresses: never javascript:, data:, file:, blob: and the like. Returns the cleaned address or ''.
function webPageUrl(raw) {
  const s = String(raw == null ? '' : raw).trim();
  if (!s || s.length > 2000) return '';
  let u;
  try { u = new URL(s); } catch { return ''; }
  if (u.protocol !== 'http:' && u.protocol !== 'https:') return '';
  if (!u.hostname) return '';
  return u.href;
}
// Why the frame cannot be shown at all, or '' if it can. An https display cannot show an http page (mixed content).
function webPageBlockedReason(url, pageProtocol) {
  if (!url) return 'Add a web address in the widget settings.';
  if (pageProtocol === 'https:' && url.indexOf('http://') === 0) return 'This display is on https, so it can only show https pages. Use an https address for this page.';
  return '';
}
// "Let this page keep its own sign-in" (wpKeepLogin): a page like Home Assistant keeps its login in its own browser storage, which the
// strict sandbox forbids. With the switch on, the frame also gets its own real origin (allow-same-origin) and may submit forms. That is
// only safe for a page on a DIFFERENT host than this app (on the same host it could read this app's cookies), so on the same host the
// switch is ignored and the box stays strict.
function webPageKeepsLogin(w, url) {
  if (!w || !w.wpKeepLogin || !url) return false;
  try { return new URL(url).hostname !== location.hostname; } catch { return false; }
}
function webPageSandbox(w, url) { return webPageKeepsLogin(w, url) ? 'allow-scripts allow-same-origin allow-forms' : 'allow-scripts'; }
function webPageFingerprint(w) { return [webPageUrl(w.wpUrl), parseInt(w.wpRefreshMin, 10) || 0, w.wpTitle || '', w.wpKeepLogin ? 1 : 0].join('|'); }
// Zoom and "scroll position". A page from another site cannot be scrolled or measured from here, so both are done to the frame
// itself: the frame is made as big as the chosen part of the page needs (the box divided by the zoom, plus the amount scrolled
// down), then scaled and shifted so that part fills the box. There is no sideways scroll: the frame is as wide as the box, so a
// page that adapts to its width fits, and Zoom handles a page built for a fixed width. Anything outside the box is clipped by .wp-view. These numbers are kept out of
// webPageFingerprint on purpose, so moving a slider never reloads the page.
function webPageView(w) {
  const num = (v, lo, hi, d) => { const n = parseInt(v, 10); return Number.isFinite(n) ? Math.max(lo, Math.min(hi, n)) : d; };
  return { zoom: num(w.wpZoom, 25, 300, 100) / 100, y: num(w.wpScrollY, 0, 10000, 0) };
}
function webPageFrameStyle(w) {
  const v = webPageView(w || {});
  return `width:calc(100% / ${v.zoom});height:calc(100% / ${v.zoom} + ${v.y}px);transform:scale(${v.zoom}) translate(0px,-${v.y}px)`;
}
// Apply a changed zoom / scroll to the frame that is already on screen: no re-render, so the page is not reloaded.
function applyWebPageView(w) {
  const frame = document.querySelector(`#canvas .widget[data-widget-id="${CSS.escape(String(w.id))}"] .wp-frame`);
  if (frame) frame.style.cssText = webPageFrameStyle(w);
}
function renderWebPage(widget) {
  const w = widget || {};
  const url = webPageUrl(w.wpUrl);
  const typed = String(w.wpUrl == null ? '' : w.wpUrl).trim();
  const why = (typed && !url) ? 'That is not a usable web address. It has to start with http:// or https://.' : webPageBlockedReason(url, location.protocol);
  const title = w.wpTitle ? `<div class="wp-title">${escapeHtmlD(w.wpTitle)}</div>` : '';
  const style = `--wp-font:${w.wpFontPx || 14}px`;
  if (why) return `<div class="w-webpage" style="${style}">${title}<div class="wp-msg">${escapeHtmlD(why)}</div></div>`;
  return `<div class="w-webpage" style="${style}">${title}<div class="wp-view"><iframe class="wp-frame" src="${escapeHtmlD(url)}" style="${webPageFrameStyle(w)}" sandbox="${webPageSandbox(w, url)}" referrerpolicy="no-referrer" title="${escapeHtmlD(w.wpTitle || 'Web page')}"></iframe></div><div class="wp-msg wp-fail" hidden>This page didn't load. Check the address — or the site may not allow being shown inside another page (Amazon, most routers and Home Assistant refuse by default).</div></div>`;
}
// After every render: watch each frame for a page that never arrives, and run the optional refresh.
function initWebPages() {
  const live = new Set();
  document.querySelectorAll('.widget-webpage[data-widget-id]').forEach((el) => {
    const id = el.dataset.widgetId; live.add(id);
    const frame = el.querySelector('.wp-frame');
    if (!frame || frame.dataset.wired === '1') return;     // reused element: already wired
    frame.dataset.wired = '1';
    const fail = el.querySelector('.wp-fail');
    const arm = () => { if (fail) fail.hidden = true; clearTimeout(frame._wpT); frame._wpT = setTimeout(() => { if (fail) fail.hidden = false; }, 25000); };
    frame.addEventListener('load', () => { clearTimeout(frame._wpT); if (fail) fail.hidden = true; });
    arm();
    const w = (state.layout || []).find((x) => String(x.id) === id) || {};
    const mins = parseInt(w.wpRefreshMin, 10) || 0;
    const old = webPageTimers.get(id); if (old) { clearInterval(old); webPageTimers.delete(id); }
    if (mins > 0) webPageTimers.set(id, setInterval(() => { try { arm(); frame.src = frame.src; } catch {} }, mins * 60000));
  });
  for (const [id, t] of webPageTimers) if (!live.has(id)) { clearInterval(t); webPageTimers.delete(id); }
}
function renderWebPageAdvancedSettings(w) {
  const mins = parseInt(w.wpRefreshMin, 10) || 0;
  const opt = (v, label) => `<option value="${v}" ${mins === v ? 'selected' : ''}>${label}</option>`;
  return `
    <div class="was-row">
      <label>Web address</label>
      <input type="text" id="wp-url" value="${escapeHtmlD(w.wpUrl || '')}" placeholder="https://example.com/page" autocapitalize="none" spellcheck="false">
    </div>
    <p class="was-hint" id="wp-url-hint" style="margin-top:-6px">${escapeHtmlD(w.wpUrl && !webPageUrl(w.wpUrl) ? 'That is not a web address. It has to start with http:// or https://' : 'Starts with http:// or https://')}</p>
    <div class="was-row">
      <label>Title (optional)</label>
      <input type="text" id="wp-title" value="${escapeHtmlD(w.wpTitle || '')}" placeholder="e.g. Homework this week">
    </div>
    <div class="was-row">
      <label>Reload the page</label>
      <select id="wp-refresh">${opt(0, 'Never')}${opt(5, 'Every 5 minutes')}${opt(15, 'Every 15 minutes')}${opt(60, 'Every hour')}</select>
    </div>
    <div class="was-row">
      <label>Zoom <span id="wp-zoom-val">${Math.round(webPageView(w).zoom * 100)}%</span></label>
      <input type="range" id="wp-zoom" min="25" max="300" step="5" value="${Math.round(webPageView(w).zoom * 100)}">
    </div>
    <div class="was-row">
      <label>Scroll down <span id="wp-scroll-y-val">${webPageView(w).y}px</span></label>
      <input type="range" id="wp-scroll-y" min="0" max="6000" step="25" value="${Math.min(6000, webPageView(w).y)}">
    </div>
    <div class="was-toggle-row">
      <label>Let this page keep its sign-in ${infoBtn("For a page that needs to remember a login, like Home Assistant. Gives the page its own storage inside the box. Only works for a page on a different computer than this one, and only turn it on for a page you trust.")}</label>
      <input type="checkbox" id="wp-keep-login" ${w.wpKeepLogin ? 'checked' : ''}>
    </div>
    <p class="was-hint">Zoom and scroll move the page inside the box; they do not reload it. The box cannot read where a page is scrolled to, so set it here.</p>
    <p class="was-hint">Shows the page inside a sandboxed box: it can run its own scripts but cannot touch this app. Works best with simple pages you host yourself that need no sign-in. Many large sites (Canvas, school portals) refuse to be shown inside another page. If your page loads a data file from its own server, that server must send an Access-Control-Allow-Origin header for it - or put the data straight into the page.</p>
  `;
}
function wireWebPageAdvancedSettings(w) {
  const url = document.getElementById('wp-url');
  if (url) url.addEventListener('change', (e) => {
    w.wpUrl = e.target.value.trim();
    const hint = document.getElementById('wp-url-hint');
    if (hint) hint.textContent = (w.wpUrl && !webPageUrl(w.wpUrl)) ? 'That is not a web address. It has to start with http:// or https://' : 'Starts with http:// or https://';
    rerenderSingleWidget(w.id); scheduleLayoutSave();      // on commit, not per keystroke: every change reloads the page
  });
  const title = document.getElementById('wp-title');
  if (title) title.addEventListener('change', (e) => { w.wpTitle = e.target.value; rerenderSingleWidget(w.id); scheduleLayoutSave(); });
  const keep = document.getElementById('wp-keep-login');
  if (keep) keep.addEventListener('change', (e) => { w.wpKeepLogin = e.target.checked; rerenderSingleWidget(w.id); scheduleLayoutSave(); });
  const refresh = document.getElementById('wp-refresh');
  if (refresh) refresh.addEventListener('change', (e) => { w.wpRefreshMin = parseInt(e.target.value, 10) || 0; rerenderSingleWidget(w.id); scheduleLayoutSave(); });
  // Sliders: applied to the frame in place while dragging (no reload), saved with the layout.
  [['wp-zoom', 'wpZoom', '%'], ['wp-scroll-y', 'wpScrollY', 'px']].forEach(([id, key, unit]) => {
    const el = document.getElementById(id);
    if (!el) return;
    el.addEventListener('input', (e) => {
      w[key] = parseInt(e.target.value, 10) || 0;
      const out = document.getElementById(id + '-val'); if (out) out.textContent = w[key] + unit;
      applyWebPageView(w); scheduleLayoutSave();
    });
  });
}
function renderQRCode(widget) {
  const w = widget || {};
  const fontPx = w.qrFontPx || 14;
  const sizePx = w.qrSizePx || 180;
  const content = qrContentFor(w);
  const style = `--qr-font:calc(${fontPx}px * var(--ui-scale,1));--qr-size:${sizePx}px`;
  if (!content) {
    return `<div class="w-qrcode" style="${style}">${w.qrTitle ? `<div class="qr-title">${escapeHtmlD(w.qrTitle)}</div>` : ''}<div class="no-data">Set content in widget settings</div></div>`;
  }
  return `<div class="w-qrcode" style="${style}">
    ${w.qrTitle ? `<div class="qr-title">${escapeHtmlD(w.qrTitle)}</div>` : ''}
    <div class="qr-card"><div class="qr-container" id="qr-c-${w.id}" data-content="${escapeHtmlD(content)}" data-size="${sizePx}"></div></div>
  </div>`;
}
// Called after every renderLayout() — (re)generates each QR widget's code into its
// fresh container div. Cheap no-op if there are no QR widgets on this layout.
function renderQRCodes() {
  if (typeof QRCode === 'undefined') return; // CDN script didn't load (e.g. no internet at boot)
  const wrapEl = document.getElementById('rotate-wrap');
  const uiScale = wrapEl ? (parseFloat(getComputedStyle(wrapEl).getPropertyValue('--ui-scale')) || 1) : 1;
  // Generate at a scaled-up native resolution too, not just display it bigger
  // via CSS — otherwise a QR code enlarged for a big screen (or a large user-
  // chosen size) would just look blurry instead of actually sharper, which
  // matters for staying reliably scannable. Same ~1.33x overscan ratio this
  // always used (240 native for a 180 display size), now proportional to
  // whatever size is actually configured instead of a fixed 240.
  document.querySelectorAll('.qr-container').forEach(el => {
    const content = el.dataset.content;
    if (!content) return;
    const displaySize = parseFloat(el.dataset.size) || 180;
    const px = Math.round(displaySize * 1.333 * uiScale);
    // qrcodejs's constructor APPENDS a freshly-drawn canvas into el — it never
    // clears any existing content first. renderQRCodes() can legitimately run
    // more than once in quick succession (applyInfoOverlay() alone can trigger
    // it from several different places — boot, an SSE push, a reconnect, a
    // profile reassignment — any of which can land close together around a
    // screen change), and without this clear, each additional call stacked
    // one more duplicate QR code into the same container instead of replacing
    // the previous one. Confirmed this was the actual library behavior, not
    // assumed — a reported "multiple QR codes appear" symptom traced directly
    // to this gap.
    el.innerHTML = '';
    try {
      new QRCode(el, { text: content, width: px, height: px, colorDark: '#000000', colorLight: '#ffffff', correctLevel: QRCode.CorrectLevel.M });
    } catch (e) { console.error('QR render failed:', e); }
  });
}

// ── Timer widget ─────────────────────────────────────────────────────────────
// Controlled from the phone app (Start/Pause/Reset live in the widget's settings
// panel there, since this wall display itself has no touch input) — this just
// displays whatever state was last pushed. Ticks every second via tickClock()
// rather than a full re-render, same pattern as the Clock widget.
function timerRemainingSec(w) {
  if (w.timerEndsAt) {
    return Math.max(0, Math.round((new Date(w.timerEndsAt).getTime() - Date.now()) / 1000));
  }
  if (typeof w.timerRemainingSec === 'number') return Math.max(0, w.timerRemainingSec);
  return Math.max(0, (w.timerMinutes || 5) * 60);
}
function fmtMMSS(totalSec) {
  const m = Math.floor(totalSec / 60), s = totalSec % 60;
  return `${m}:${String(s).padStart(2, '0')}`;
}
function renderTimer(widget) {
  const w = widget || {};
  const fontPx = w.timerFontPx || 32;
  const remaining = timerRemainingSec(w);
  const isRunning = !!w.timerEndsAt;
  const isPaused = !isRunning && typeof w.timerRemainingSec === 'number' && w.timerRemainingSec > 0;
  const isDone = isRunning && remaining <= 0;
  let statusLabel = 'Ready';
  if (isDone) statusLabel = '⏰ Time\'s Up!';
  else if (isRunning) statusLabel = 'Running';
  else if (isPaused) statusLabel = 'Paused ⏸';
  return `<div class="w-timer${isDone ? ' timer-done' : ''}" style="--timer-font:calc(${fontPx}px * var(--ui-scale,1))">
    ${w.timerTitle ? `<div class="timer-title">${escapeHtmlD(w.timerTitle)}</div>` : ''}
    <div class="timer-display" data-ends-at="${w.timerEndsAt || ''}" data-fallback="${remaining}">${fmtMMSS(remaining)}</div>
    <div class="timer-status">${statusLabel}</div>
  </div>`;
}

// ── Layout Switcher widget ────────────────────────────────────────────────────
// A row of buttons, one per saved layout OR live display this instance is
// configured to offer — tapping one calls switchToLayoutTarget() (see its
// own comment, above fetchLayoutAndRender, for the full pre-fetch/instant-swap
// mechanic). This widget only renders the buttons; all the actual
// switching logic lives there, shared with the screen-level floating
// switcher (renderFloatingSwitcher() below) rather than duplicated.
// Shared by both switcher surfaces (widget + floating) — looks up a
// target's display name from whichever cache matches its type, falling
// back to a generic label if that cache hasn't loaded yet (the very first
// render after boot, before prefetchSwitcherPresets() has fetched names —
// see its own "namesFreshlyLoaded" re-render for how this self-corrects).
function switcherTargetLabel(target) {
  if (target.type === 'display') {
    const d = (state._switcherDisplayNamesCache || []).find(x => x.slug === target.id);
    return d ? d.name : `Display: ${target.id}`;
  }
  const p = (state._switcherNamesCache || []).find(x => Number(x.id) === Number(target.id));
  return p ? p.name : `Layout #${target.id}`;
}
function renderLayoutSwitcher(widget) {
  const w = widget || {};
  const fontPx = w.switcherFontPx || 15;
  const style = `--ls-font:calc(${fontPx}px * var(--ui-scale,1))`;
  const targets = normalizeSwitcherTargets(w.switcherTargets || w.switcherPresetIds);
  if (!targets.length) {
    return `<div class="w-layoutswitcher" style="${style}"><div class="no-data">No layouts assigned yet — set this up from the app.</div></div>`;
  }
  const buttons = targets.map(t =>
    `<button type="button" class="ls-btn" data-target-type="${t.type}" data-target-id="${escapeHtmlD(String(t.id))}">${escapeHtmlD(switcherTargetLabel(t))}</button>`
  ).join('');
  return `<div class="w-layoutswitcher" style="${style}"><div class="ls-buttons">${buttons}</div></div>`;
}

// ── On This Day widget ───────────────────────────────────────────────────────
function renderOnThisDay(widget) {
  const w = widget || {};
  const fontPx = w.otdFontPx || 15;
  const style = `--otd-font:calc(${fontPx}px * var(--ui-scale,1))`;
  if (!state.onThisDay) {
    if (state.onThisDayError) {
      return `<div class="w-onthisday" style="${style}"><div class="otd-head">On This Day</div><div class="no-data">${escapeHtmlD(state.onThisDayError)}</div></div>`;
    }
    return `<div class="w-onthisday" style="${style}"><div class="otd-head">On This Day</div><div class="no-data">Loading…</div></div>`;
  }
  const maxItems = w.otdMaxItems || 4;
  const items = (state.onThisDay.events || []).slice(0, maxItems);
  if (!items.length) {
    return `<div class="w-onthisday" style="${style}"><div class="otd-head">On This Day</div><div class="no-data">Nothing found for today</div></div>`;
  }
  const rows = items.map(e => `
    <div class="otd-item">
      <div class="otd-year">${e.year}</div>
      <div class="otd-text">${escapeHtmlD(e.text)}</div>
    </div>`).join('');
  return `<div class="w-onthisday" style="${style}"><div class="otd-head">On This Day</div><div class="otd-list">${rows}</div></div>`;
}

// ── Daily Quote widget ───────────────────────────────────────────────────────
function renderDailyQuote(widget) {
  const w = widget || {};
  const fontPx = w.dqFontPx || 20;
  const style = `--dq-font:calc(${fontPx}px * var(--ui-scale,1))`;
  if (!state.dailyQuote) {
    if (state.dailyQuoteError) {
      return `<div class="w-dailyquote" style="${style}"><div class="no-data">${escapeHtmlD(state.dailyQuoteError)}</div></div>`;
    }
    return `<div class="w-dailyquote" style="${style}"><div class="no-data">Loading…</div></div>`;
  }
  const q = state.dailyQuote;
  return `<div class="w-dailyquote" style="${style}">
    <div class="dq-mark">"</div>
    <div class="dq-text">${escapeHtmlD(q.quote)}</div>
    <div class="dq-author">— ${escapeHtmlD(q.author)}</div>
  </div>`;
}

// ── Sports Scores widget ─────────────────────────────────────────────────────
function renderSports(widget) {
  const w = widget || {};
  const fontPx = w.spFontPx || 16;
  const style = `--sp-font:calc(${fontPx}px * var(--ui-scale,1))`;
  if (!w.spTeamId) {
    return `<div class="w-sports" style="${style}"><div class="no-data">Pick a team in widget settings</div></div>`;
  }
  const key = String(w.spTeamId);
  const data = state.sports && state.sports[key];
  const err = state.sportsError && state.sportsError[key];
  if (!data) {
    return `<div class="w-sports" style="${style}">
      ${w.spTeamBadge ? `<img class="sp-badge" src="${escapeHtmlD(w.spTeamBadge)}" alt="">` : ''}
      <div class="sp-team">${escapeHtmlD(w.spTeamName || 'Team')}</div>
      <div class="no-data">${err ? escapeHtmlD(err) : 'Loading…'}</div>
    </div>`;
  }
  const fmtGame = (e, isNext) => {
    if (!e) return `<div class="sp-empty">${isNext ? 'No upcoming game found' : 'No recent game found'}</div>`;
    const homeIsTeam = (e.home || '').toLowerCase() === (w.spTeamName || '').toLowerCase();
    const scoreKnown = e.homeScore != null && e.awayScore != null;
    let scoreLine = '';
    if (scoreKnown) {
      const teamScore = homeIsTeam ? e.homeScore : e.awayScore;
      const oppScore = homeIsTeam ? e.awayScore : e.homeScore;
      const result = teamScore > oppScore ? 'W' : teamScore < oppScore ? 'L' : 'T';
      scoreLine = `<span class="sp-result sp-${result.toLowerCase()}">${result}</span> ${e.homeScore}–${e.awayScore}`;
    }
    return `
      <div class="sp-matchup">${escapeHtmlD(e.home)} vs ${escapeHtmlD(e.away)}</div>
      ${scoreKnown ? `<div class="sp-score">${scoreLine}</div>` : `<div class="sp-date">${escapeHtmlD(e.date)}${e.time ? ' · ' + escapeHtmlD(e.time) : ''}</div>`}
    `;
  };
  return `<div class="w-sports" style="${style}">
    ${w.spTeamBadge ? `<img class="sp-badge" src="${escapeHtmlD(w.spTeamBadge)}" alt="">` : ''}
    <div class="sp-team">${escapeHtmlD(w.spTeamName || 'Team')}</div>
    <div class="sp-section">
      <div class="sp-label">Next Game</div>
      ${fmtGame(data.nextEvent, true)}
    </div>
    <div class="sp-section">
      <div class="sp-label">Last Game</div>
      ${fmtGame(data.lastEvent, false)}
    </div>
  </div>`;
}

// ── METAR/TAF widget ──────────────────────────────────────────────────────────
const FLIGHT_CAT_COLOR = { VFR: '#3ec97a', MVFR: '#4aa3ff', IFR: '#fb7185', LIFR: '#e879f9' };
function relTimeAgo(ms) {
  if (!ms) return '';
  const mins = Math.round((Date.now() - ms) / 60000);
  if (mins < 1) return 'just now';
  if (mins < 60) return `${mins}m ago`;
  const hrs = Math.round(mins / 60);
  return `${hrs}h ago`;
}
function renderMetarTaf(widget) {
  const w = widget || {};
  const fontPx = w.wxFontPx || 16;
  const style = `--wx-font:calc(${fontPx}px * var(--ui-scale,1))`;
  if (!w.wxIcao) {
    return `<div class="w-metar" style="${style}"><div class="no-data">Enter an airport ICAO code in widget settings</div></div>`;
  }
  const key = String(w.wxIcao).toUpperCase();
  const data = state.metarTaf && state.metarTaf[key];
  const err = state.metarTafError && state.metarTafError[key];
  if (!data) {
    return `<div class="w-metar" style="${style}"><div class="wx-station">${escapeHtmlD(key)}</div><div class="no-data">${err ? escapeHtmlD(err) : 'Loading…'}</div></div>`;
  }
  const m = data.metar;
  const showTaf = w.wxShowTaf !== false;
  const cToF = (c) => c == null ? null : Math.round(c * 9 / 5 + 32);
  const metarHtml = m ? `
    <div class="wx-main">
      <div class="wx-station">${escapeHtmlD(data.name || key)}</div>
      ${m.flightCategory ? `<div class="wx-catbadge" style="background:${FLIGHT_CAT_COLOR[m.flightCategory] || '#888'}">${m.flightCategory}</div>` : ''}
    </div>
    <div class="wx-temp">${cToF(m.tempC) != null ? cToF(m.tempC) + '°F' : '—'} <span class="wx-dewp">/ ${cToF(m.dewpC) != null ? cToF(m.dewpC) + '°F dewpoint' : ''}</span></div>
    <div class="wx-details">
      <div class="wx-item"><span>Wind</span><span>${m.windSpeedKt != null ? (m.windSpeedKt === 0 ? 'Calm' : `${m.windDir != null ? m.windDir + '°' : ''} ${m.windSpeedKt}kt${m.windGustKt ? ' G' + m.windGustKt : ''}`) : '—'}</span></div>
      <div class="wx-item"><span>Visibility</span><span>${m.visibSM != null ? m.visibSM + ' SM' : '—'}</span></div>
      <div class="wx-item"><span>Altimeter</span><span>${m.altimInHg != null ? m.altimInHg.toFixed(2) + ' inHg' : '—'}</span></div>
      <div class="wx-item"><span>Sky</span><span>${escapeHtmlD(m.sky)}</span></div>
      ${m.wx ? `<div class="wx-item"><span>Weather</span><span>${escapeHtmlD(m.wx)}</span></div>` : ''}
    </div>
    <div class="wx-obs">Observed ${relTimeAgo(m.obsTime)}</div>
  ` : `<div class="wx-station">${escapeHtmlD(key)}</div><div class="no-data">No current METAR available</div>`;

  const taf = data.taf;
  const tafHtml = (showTaf && taf) ? `
    <div class="wx-taf-head">Forecast (TAF)</div>
    <div class="wx-taf-raw">${escapeHtmlD(taf.raw || 'No TAF text available')}</div>
  ` : '';

  return `<div class="w-metar" style="${style}">${metarHtml}${tafHtml}</div>`;
}

// Persisted (survives reloads) cache of "is this photo landscape" per filename —
// this is an intrinsic property of the photo file that never changes, so once
// known, it's known forever on this device. Used by 'auto' fit mode to decide
// the correct object-fit BEFORE the image ever paints, instead of always
// starting with 'contain' and upgrading after onload fires — which is what
// caused the brief flash of letterboxing before snapping to full-bleed on
// every single photo, every time, even ones already shown many times before.
function getCachedPhotoOrientation(filename) {
  try {
    const cache = JSON.parse(localStorage.getItem('photoOrientationCache') || '{}');
    return cache[filename]; // true=landscape, false=portrait, undefined=unknown yet
  } catch { return undefined; }
}
function setCachedPhotoOrientation(filename, isLandscape) {
  try {
    const cache = JSON.parse(localStorage.getItem('photoOrientationCache') || '{}');
    cache[filename] = isLandscape;
    // Simple cap so this can't grow unbounded over a very long-lived kiosk —
    // trims the oldest half once it gets large rather than tracking real LRU.
    const keys = Object.keys(cache);
    if (keys.length > 2000) { for (const k of keys.slice(0, 1000)) delete cache[k]; }
    localStorage.setItem('photoOrientationCache', JSON.stringify(cache));
  } catch {}
}

// Shared by renderPhotoWidget (initial render) and crossfadePhotoWidget (in-place
// slideshow update) so the auto-fit/blur-background logic only lives in one place.
function computePhotoFitStyle(p, w) {
  const fitMode = w.photoFit || 'cover';
  let imgFit = 'cover';
  let blurLayer = '';
  if (fitMode === 'width') imgFit = 'object-fit:contain;width:100%;height:auto;max-height:100%;margin:auto';
  else if (fitMode === 'height') imgFit = 'object-fit:contain;height:100%;width:auto;max-width:100%;margin:auto';
  else if (fitMode === 'auto') {
    const widgetPxW = (Number(w.w) || 0) / 100 * effectiveWidth();
    const widgetPxH = (Number(w.h) || 0) / 100 * effectiveHeight();
    const widgetLandscape = widgetPxW >= widgetPxH;
    const cachedLandscape = getCachedPhotoOrientation(p.filename);
    const wantBlurBg = w.photoAutoBlurBg !== false;
    if (cachedLandscape !== undefined) {
      const matches = cachedLandscape === widgetLandscape;
      imgFit = matches ? 'object-fit:cover;width:100%;height:100%' : 'object-fit:contain;width:100%;height:100%';
      if (!matches && wantBlurBg) {
        blurLayer = `<img class="w-photo-blurbg" src="/uploads/${p.filename}" alt="" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;filter:blur(28px) brightness(0.5);transform:scale(1.15);z-index:0">`;
      }
    } else {
      imgFit = 'object-fit:contain;width:100%;height:100%';
      if (wantBlurBg) {
        blurLayer = `<img class="w-photo-blurbg" src="/uploads/${p.filename}" alt="" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;filter:blur(28px) brightness(0.5);transform:scale(1.15);z-index:0;display:none">`;
      }
    }
  } else {
    imgFit = 'object-fit:cover;width:100%;height:100%';
  }
  return { imgFit, blurLayer };
}

function renderPhotoWidget(widget) {
  const photos = photosForWidget(widget);
  const p = photos[getSlideIndexForWidget(widget) % Math.max(1, photos.length)];
  if(!p) return `<div class="w-photo" style="background:rgba(255,255,255,0.05)"></div>`;
  const ps = state.photoSettings || {};
  const opacity = parseInt(ps.opacity ?? 100) / 100;
  // Edge fade now lives on the WIDGET (set in the Layout editor), not the global
  // photo settings — so each photo widget can blend its own edges independently.
  const w = widget || {};
  const fitMode = w.photoFit || 'cover';
  const { imgFit, blurLayer } = computePhotoFitStyle(p, w);
  const fadeMask = buildEdgeFadeMask(
    parseInt(w.fadeTop || 0), parseInt(w.fadeBottom || 0),
    parseInt(w.fadeLeft || 0), parseInt(w.fadeRight || 0)
  );
  // A full-canvas photo widget (the ambient full-screen mode, or any normal
  // widget someone's deliberately sized to fill the whole screen) shouldn't have
  // the normal small-tile rounded corners — at 100% size that just clips small
  // triangles of the photo at each corner, which can look like it doesn't
  // properly fill/fit its container.
  const isFullBleed = Number(w.w) >= 100 && Number(w.h) >= 100 && Number(w.x) <= 0 && Number(w.y) <= 0;
  const radiusOverride = isFullBleed ? 'border-radius:0;' : '';
  const onload = fitMode === 'auto' ? ` onload="handleAutoFitPhotoLoad(this, '${p.filename.replace(/'/g, "\\'")}')"` : '';
  return `<div class="w-photo" style="position:relative;display:flex;align-items:center;justify-content:center;flex:1;min-height:0;width:100%;overflow:hidden;${radiusOverride}">
    ${blurLayer}
    <img class="w-photo-main" src="/uploads/${p.filename}" alt="" style="position:relative;z-index:1;opacity:${opacity.toFixed(2)};${imgFit}${fadeMask}"${onload}>
  </div>`;
}
// Crossfades a photo widget's image in-place (no full canvas rebuild) when the
// slideshow advances. The alternative — a hard, instant cut — was the only
// option available previously, since renderLayout() wipes and rebuilds the
// ENTIRE canvas every time it runs (canvas.innerHTML=''), leaving nothing to
// fade FROM. This bypasses that entirely for photo widgets specifically, which
// is also a real (if secondary) performance win: nothing else on screen
// actually changes when only slideIndex advances, so rebuilding every other
// widget too was always wasted work. Falls back to an instant swap if fade is
// turned off for this widget, or the expected DOM structure isn't there.
function crossfadePhotoWidget(el, w) {
  const photos = photosForWidget(w);
  const p = photos[getSlideIndexForWidget(w) % Math.max(1, photos.length)];
  const wrap = el.querySelector('.w-photo');
  if (!p || !wrap) { el.innerHTML = renderWidget(w); return; }

  const oldImg = wrap.querySelector('img.w-photo-main');
  if (!oldImg || w.photoFadeTransition === false) {
    el.innerHTML = renderWidget(w); // no image to fade from, or fade turned off
    return;
  }

  const ps = state.photoSettings || {};
  const targetOpacity = parseInt(ps.opacity ?? 100) / 100;
  const { imgFit, blurLayer } = computePhotoFitStyle(p, w);
  const fitMode = w.photoFit || 'cover';

  // Crossfade the blurred background IN SYNC with the main photo, rather than
  // swapping it instantly — that meant the background could already show the
  // NEXT photo's blur while the CURRENT photo was still visibly fading out in
  // front of it, its own jarring mismatch, worse than what the fade was meant
  // to smooth over. Built as a real element (not via insertAdjacentHTML) so
  // there's a direct reference to it — both old and new blur layers briefly
  // share the same class during the transition, which would otherwise make a
  // plain querySelector('.w-photo-blurbg') ambiguous about which one it means.
  // User-configurable — w.photoFadeDuration is in seconds (Layout tab / ambient
  // mode's own settings), defaulting to 2s if never set. Clamped to a sane
  // range so a stray value can't produce something absurd either direction.
  const FADE_MS = Math.min(10, Math.max(0.5, parseFloat(w.photoFadeDuration) || 2)) * 1000;
  const oldBlurImg = wrap.querySelector('img.w-photo-blurbg');
  let newBlurImg = null;
  if (blurLayer) {
    newBlurImg = document.createElement('img');
    newBlurImg.className = 'w-photo-blurbg';
    newBlurImg.alt = '';
    newBlurImg.style.cssText = `position:absolute;inset:0;width:100%;height:100%;object-fit:cover;filter:blur(28px) brightness(0.5);transform:scale(1.15);z-index:0;opacity:0;transition:opacity ${FADE_MS}ms ease-in-out`;
    newBlurImg.src = `/uploads/${p.filename}`;
    wrap.insertBefore(newBlurImg, wrap.firstChild);
  }

  const newImg = document.createElement('img');
  newImg.className = 'w-photo-main';
  newImg.alt = '';
  const fadeMask = buildEdgeFadeMask(
    parseInt(w.fadeTop || 0), parseInt(w.fadeBottom || 0),
    parseInt(w.fadeLeft || 0), parseInt(w.fadeRight || 0)
  );
  // Starts with NO transition set yet — added only once the image has actually
  // loaded (see below). Setting it now, before there's anything to see, would
  // let the fade clock start running against a still-invisible image: by the
  // time the photo actually appears, a chunk of the fade would already be
  // spent, making the VISIBLE portion shorter and more abrupt than intended.
  newImg.style.cssText = `position:absolute;inset:0;z-index:1;opacity:0;${imgFit}${fadeMask}`;
  const startFade = () => {
    if (fitMode === 'auto') handleAutoFitPhotoLoad(newImg, p.filename, newBlurImg);
    newImg.style.transition = `opacity ${FADE_MS}ms ease-in-out`;
    oldImg.style.transition = `opacity ${FADE_MS}ms ease-in-out`;
    if (oldBlurImg) oldBlurImg.style.transition = `opacity ${FADE_MS}ms ease-in-out`;
    requestAnimationFrame(() => requestAnimationFrame(() => {
      newImg.style.opacity = targetOpacity.toFixed(2);
      oldImg.style.opacity = '0';
      if (newBlurImg) newBlurImg.style.opacity = '1';
      if (oldBlurImg) oldBlurImg.style.opacity = '0';
    }));
    setTimeout(() => {
      oldImg.remove();
      if (oldBlurImg) oldBlurImg.remove();
    }, FADE_MS + 100);
  };
  newImg.addEventListener('load', startFade, { once: true });
  // A broken/missing file should never leave the OLD photo stuck on screen
  // forever waiting for a load event that's never coming — fall back to
  // starting the transition anyway (the new image will just show as broken).
  newImg.addEventListener('error', startFade, { once: true });
  newImg.src = `/uploads/${p.filename}`;
  wrap.appendChild(newImg);

  // The old image was position:relative as the only layer before — switch it to
  // absolute too so both stack correctly on top of each other during the fade.
  oldImg.style.position = 'absolute';
  oldImg.style.inset = '0';
}

// Companion to 'auto' fit mode — runs once a photo's image has actually loaded
// and its real dimensions are known FOR THE FIRST TIME (subsequent showings of
// the same photo skip straight to the correct fit via the cache above, no
// onload round-trip needed). Records the photo's orientation for next time, and
// upgrades THIS instance immediately if the orientations already turned out to
// match (nothing to do if they don't — it's already correctly in 'contain').
// blurEl (optional): the SPECIFIC blur element to hide if not needed — passed
// explicitly during a crossfade, where two blur layers briefly coexist and a
// plain class lookup could hide the wrong one; omitted for the initial, non-
// crossfade render, where there's only ever one and no ambiguity.
window.handleAutoFitPhotoLoad = function(img, filename, blurEl) {
  const wrap = img.closest('.w-photo');
  if (!wrap) return;
  const photoLandscape = img.naturalWidth >= img.naturalHeight;
  setCachedPhotoOrientation(filename, photoLandscape);
  const wrapLandscape = wrap.offsetWidth >= wrap.offsetHeight;
  if (photoLandscape === wrapLandscape) {
    img.style.objectFit = 'cover';
    const bg = blurEl || wrap.querySelector('.w-photo-blurbg');
    if (bg) bg.style.display = 'none';
  }
};

// ── Background photo / slideshow ─────────────────────────────────────────────
// One single, always-running timer that advances the shared slideIndex and
// re-renders. Every photo-consuming thing (a normal Photo widget, the ambient
// full-screen photo layout, or the old Tab-key blank background) reads this
// same counter with its own modulo against its own photo list — so one timer
// correctly drives all of them, rather than each needing its own.
let _slideTimerMs = 0; // interval the running shared timer was built for (0 = not running)
// Safe to call any time photo settings might have changed (page load, the
// photo-settings SSE topic, the periodic settings refresh): it starts the timer
// if slideshow was just switched on, stops it if switched off, re-times it if the
// interval changed, and otherwise leaves the running timer (and its countdown)
// alone. It used to run once at page load only, so turning the slideshow on -
// or changing its interval - from the app did nothing on a display that was
// already open until that display reloaded.
function startSlideshowTimer() {
  const ps = state.photoSettings || {};
  const wantMs = ps.slideshow === '1' ? Math.max(5, parseInt(ps.slideshow_interval || 30) || 30) * 1000 : 0;
  if (wantMs === _slideTimerMs && (wantMs === 0 || slideTimer)) return;
  if (slideTimer) { clearInterval(slideTimer); slideTimer = null; }
  _slideTimerMs = wantMs;
  if (!wantMs) return; // global slideshow toggle is off - no cycling
  const iv = wantMs;
  slideTimer = setInterval(() => {
    const total = (state.photos || []).length;
    if (!total) return;
    slideIndex = (slideIndex + 1) % total;
    // Update only photo widgets in place (with a crossfade) — nothing else on
    // screen actually changes when just slideIndex advances, and a full
    // renderLayout() would wipe and rebuild everything (canvas.innerHTML=''),
    // which is both wasted work for every non-photo widget AND incompatible
    // with a smooth crossfade, since there'd be nothing left to fade FROM.
    document.querySelectorAll('#canvas .widget-photo').forEach(el => {
      const w = state.layout.find(ww => String(ww.id) === el.dataset.widgetId);
      // Skip widgets with their own custom interval — they're advanced by their
      // own independent timer instead (see syncPerWidgetPhotoTimers), and
      // updating them here too would double-advance and desync their own index.
      if (w && !w.photoInterval) crossfadePhotoWidget(el, w);
    });
    applyBackground();
  }, iv);
}

function applyBackground(forcePhotoBg = false) {
  const ps = state.photoSettings;
  const bg = document.getElementById('photo-bg');
  const ov = document.getElementById('photo-overlay');
  const hasPhotoWidget = state.layout.some(w=>w.type==='photo');
  // In blank mode the widgets are hidden, so always show the background photo.
  const blanked = document.body.classList.contains('blanked');
  const forcePhoto = forcePhotoBg || blanked;

  // Normally the full-screen background photo is suppressed when a photo *widget*
  // is present (so they don't fight). But in blank mode the widgets are hidden, so
  // we force the background photo on to fill the screen — that's the whole point
  // of the Tab blank view: a clean photo, no widgets.
  let bgPhotos = (hasPhotoWidget && !forcePhoto) ? [] : activePhotos();

  // Tab/blank view honors the chosen blank_mode (Settings → Photos → Tab View):
  //   'black'  → blackout: hide the photo entirely, show a black screen
  //   'single' → one chosen photo, no cycling
  //   'slideshow' (default) → cycle the selected photos
  let blankMode = null;
  if (blanked) {
    blankMode = ps.blank_mode || 'slideshow';
    if (blankMode === 'black') {
      bg.classList.remove('show');
      bg.style.backgroundImage = '';
      const fc = document.getElementById('photo-fade-overlays');
      if (fc) fc.innerHTML = '';
      // Not clearing slideTimer here anymore — it's a single shared timer now
      // (see startSlideshowTimer), started once and left running regardless of
      // this mode; clearing it here would kill slideshow advancement for every
      // other context too, permanently, since nothing would ever restart it.
      return;
    }
    if (blankMode === 'single') {
      const all = (state.photos || []);
      const chosen = all.find(p => String(p.id) === String(ps.blank_photo_id));
      bgPhotos = chosen ? [chosen] : (activePhotos().length ? activePhotos() : all);
    }
  }

  // In blank mode (Tab), never fall to a black screen unless that's the chosen mode:
  // if there are no globally "active" photos, fall back to widget photos, then all.
  if (forcePhoto && !bgPhotos.length) {
    const fromWidgets = [];
    (state.layout || []).filter(w => w.type === 'photo').forEach(w => {
      photosForWidget(w).forEach(p => { if (!fromWidgets.some(x => x.id === p.id)) fromWidgets.push(p); });
    });
    bgPhotos = fromWidgets.length ? fromWidgets : (state.photos || []);
  }
  if(!bgPhotos.length) {
    bg.classList.remove('show');
    const fadeContainer = document.getElementById('photo-fade-overlays');
    if (fadeContainer) fadeContainer.innerHTML = '';
    return;
  }

  const p = bgPhotos[slideIndex % bgPhotos.length];
  const darkness = 1 - (parseInt(ps.brightness??40)/100);
  const opacity  = parseInt(ps.opacity??100)/100;
  ov.style.background = `rgba(10,14,26,${darkness.toFixed(2)})`;
  bg.style.setProperty('--photo-opacity', opacity.toFixed(2));
  bg.style.opacity='0';
  // Global edge-fade was removed — edge fade is now a per-photo-widget option.
  const fadeContainer = document.getElementById('photo-fade-overlays');
  if (fadeContainer) fadeContainer.innerHTML = '';
  setTimeout(()=>{ bg.style.backgroundImage=`url('/uploads/${p.filename}')`; bg.classList.add('show'); }, 400);
  // Slideshow advancement lives in one shared timer (see startSlideshowTimer) —
  // not set up here anymore. It used to only run when THIS function's own
  // bgPhotos had more than one entry, which meant a normal Photo widget (whose
  // photos live in a separate list entirely) never got any slideshow timer of
  // its own at all — configuring multiple photos on a widget just showed the
  // same one forever. One shared timer, driving one shared slideIndex that
  // every photo-consuming thing (this function, a widget, the new ambient
  // layout) reads from with its own modulo, fixes that for all of them at once.
}

// ── Data fetching ────────────────────────────────────────────────────────────
// Recent window: refreshed often (every few minutes) — current + upcoming.
// Pulls the whole chore chart (all kids + their day's chores) for the wall widget.
async function fetchChoreChart() {
  try {
    const r = await fetch('/api/chore-chart');
    state.choreChart = await r.json();
  } catch { state.choreChart = null; }
}

// Sticker records for the calendar widget's opt-in day-cell badges. Only
// fetched at all when some minical widget on this layout actually has
// calShowStickers on — same "don't do work nothing's using" reasoning as
// fetchTodoForLayout()/fetchShoppingListForLayout() below. A wide-ish range
// (45 days back, 90 forward) covers ordinary month-view swipe navigation
// without needing to re-fetch on every nav step.
async function fetchStickersForLayout() {
  const wantsStickers = state.layout.some(w => w.type === 'minical' && w.calShowStickers);
  if (!wantsStickers) { state.stickers = []; return; }
  const from = (()=>{ const d=new Date(); d.setDate(d.getDate()-45); return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`; })();
  const to = (()=>{ const d=new Date(); d.setDate(d.getDate()+90); return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`; })();
  try {
    const r = await fetch(`/api/stickers?from=${from}&to=${to}`);
    state.stickers = await r.json();
  } catch { state.stickers = state.stickers || []; }
}

// Built-in To-Do widget's data — deliberately separate from the Todoist-backed
// Tasks widget's fetchTasksForLayout(). Only fetches lists actually referenced
// by a 'todo' widget in the current layout, same efficiency reasoning as that
// function already uses for Todoist projects.
async function fetchTodoForLayout() {
  const todoWidgets = state.layout.filter(w => w.type === 'todo');
  if (!todoWidgets.length) return;
  try {
    const r = await fetch('/api/todo-lists');
    state.todoListsMeta = await r.json();
  } catch { state.todoListsMeta = state.todoListsMeta || []; }
  const listIds = [...new Set(todoWidgets.map(w => w.listId).filter(Boolean))];
  state.todoItems = state.todoItems || {};
  await Promise.all(listIds.map(async (id) => {
    try {
      const r = await fetch(`/api/todo-lists/${id}/items`);
      state.todoItems[id] = await r.json();
    } catch { state.todoItems[id] = state.todoItems[id] || []; }
  }));
}

async function fetchShoppingListForLayout() {
  if (!state.layout.some(w => w.type === 'shoppinglist')) return; // skip work if no widget is in use
  try {
    // ?list=all: every list's items in one fetch (each carries its list_id), so
    // several widgets can each show a different list. A host that predates lists
    // ignores the param and returns its one list, which the widget accepts as-is.
    const [r, lr] = await Promise.all([fetch('/api/shopping-list?list=all'), fetch('/api/shopping-lists').catch(() => null)]);
    state.shoppingItems = await r.json();
    if (lr && lr.ok) { const l = await lr.json(); state.shoppingLists = Array.isArray(l) ? l : []; }
    else state.shoppingLists = state.shoppingLists || [];
  } catch { state.shoppingItems = state.shoppingItems || []; state.shoppingLists = state.shoppingLists || []; }
}

async function fetchEvents() {
  const from = (()=>{ const d=new Date(); d.setDate(d.getDate()-7); return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`; })();
  const to = (()=>{ const d=new Date(); d.setDate(d.getDate()+60); return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`; })();
  const r = await fetch(`/api/events?from=${from}&to=${to}`);
  state.eventsRecent = await r.json();
  mergeEvents();
}

// Reminders: unlike events, these aren't date-windowed server-side — the
// list itself is small (a handful of household rotations, not a growing
// history), and the schedule_config on each one is enough to compute
// whether it's due on any given date entirely client-side (see
// reminderOccursOnDate() below). So this just pulls the whole list.
async function fetchReminders() {
  try {
    const r = await fetch('/api/reminders');
    state.reminders = await r.json();
  } catch { state.reminders = state.reminders || []; }
}

// Family Message Board notes. Like reminders, not date-windowed — the server
// caps the table at 60 rows and auto-clears old ones, so this pulls the whole
// list. Kept live via the 'messages' SSE topic; this is just the initial load
// and a daily safety-net refresh.
async function fetchMessages() {
  try {
    const r = await fetch('/api/messages');
    state.messages = await r.json();
  } catch { state.messages = state.messages || []; }
}

// Weekly meal plan (the "mealplan" widget). Stored as an object keyed by
// 'YYYY-MM-DD' -> { [slot]: row } for O(1) lookup. Kept live via the 'meals'
// SSE topic; this is the initial load + a daily refresh.
async function fetchMeals() {
  try {
    const from = todayStr();
    const to = (() => { const d = new Date(); d.setDate(d.getDate() + 45); return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`; })();
    const rows = await (await fetch(`/api/meals?from=${from}&to=${to}`)).json();
    const byDate = {};
    (Array.isArray(rows) ? rows : []).forEach(m => {
      (byDate[m.date] = byDate[m.date] || {})[m.slot || 'dinner'] = m;
    });
    state.meals = byDate;
  } catch { state.meals = state.meals || {}; }
}

// Cameras for the Camera widget. The list carries no stream URLs (the server
// redacts them) — just id/name/kind so the widget knows which /api/camera/<id>
// endpoints to hit. _cameraServiceState tracks whether this display's local
// go2rtc media process is available; 'unknown' until we've asked once.
let _cameraServiceState = 'unknown';
async function fetchCameras() {
  try {
    const r = await fetch('/api/cameras');
    state.cameras = await r.json();
  } catch { state.cameras = state.cameras || []; }
  try {
    const s = await (await fetch('/api/camera/service')).json();
    if (s && s.state) _cameraServiceState = s.state;
  } catch {}
}

// Family member profiles — used here only to colour-code local events by
// their owner (owner_profile_id). The wall has no "active profile"; this is
// purely a lookup table. Empty on a household that hasn't set any up.
let _profileColorById = new Map();
async function fetchProfiles() {
  try {
    const r = await fetch('/api/profiles');
    const list = await r.json();
    state.profiles = Array.isArray(list) ? list : [];
  } catch { state.profiles = state.profiles || []; }
  _profileColorById = new Map((state.profiles || []).map(p => [Number(p.id), p.color]));
}
function profileNameByIdD(id) {
  const p = (state.profiles || []).find(x => Number(x.id) === Number(id));
  return p ? p.name : '';
}
function profileByIdD(id) {
  return (state.profiles || []).find(x => Number(x.id) === Number(id)) || null;
}
// Small round avatar chip (emoji on the profile's colour) — the wall version
// of app.html's profileAvatarHtml.
function profileAvatarHtmlD(p, px) {
  if (!p) return '';
  const s = px || 16;
  const face = (p.avatar || '').trim() || (p.name || '?').trim().charAt(0).toUpperCase() || '?';
  return `<span class="profile-avatar-d" style="width:${s}px;height:${s}px;font-size:${Math.round(s * 0.55)}px;background:${escapeHtmlD(p.color || '#4A90D9')}">${escapeHtmlD(face)}</span>`;
}

// Does this reminder occur on the given date (a 'YYYY-MM-DD' string)? The
// one shared helper both the Reminders widget and the calendar-grid/Agenda
// integrations call, so "is this due" can never disagree between them.
// ── Reminder recurrence engine ──────────────────────────────────────────────
// Identical logic to reminderOccursOnDateServer() and its helpers in
// server.js — see that copy's own comment for the full field reference and
// design rationale (iOS Calendar's custom-recurrence picker as the model,
// every new field additive/optional so pre-existing reminders keep working
// unchanged, 'afterCount' end conditions counted via a bounded day-by-day
// scan rather than four separate closed-form formulas). Kept as its own
// implementation here rather than shared, matching how this file and
// server.js have never shared code — different runtime environments
// (browser vs. Node), and every other piece of duplicated logic in this
// codebase (opacity resolution, theme fixes, etc.) already follows the
// same pattern of two carefully-matched copies.
const REMINDER_COUNT_SCAN_CAP_DAYS = 3650;
function reminderDaysBetween(a, b) { return Math.round((b - a) / 86400000); }
function reminderStartOfWeek(d) { const x = new Date(d); x.setDate(x.getDate() - x.getDay()); return x; }
function reminderNthWeekdayOfMonth(year, month0, weekday, nth) {
  if (nth === -1) {
    const last = new Date(year, month0 + 1, 0);
    const offset = (last.getDay() - weekday + 7) % 7;
    return new Date(year, month0, last.getDate() - offset);
  }
  const first = new Date(year, month0, 1);
  const offset = (weekday - first.getDay() + 7) % 7;
  const day = 1 + offset + (nth - 1) * 7;
  const d = new Date(year, month0, day);
  return d.getMonth() === month0 ? d : null;
}
function reminderMatchesPattern(reminder, d) {
  const cfg = reminder.schedule_config || {};
  const type = reminder.schedule_type;
  if (type === 'weekly') {
    if (!Array.isArray(cfg.daysOfWeek) || !cfg.daysOfWeek.includes(d.getDay())) return false;
    if (cfg.startDate) {
      const start = new Date(cfg.startDate + 'T00:00:00');
      if (d < start) return false;
      const interval = cfg.weekInterval || 1;
      if (interval > 1) {
        const weeks = reminderDaysBetween(reminderStartOfWeek(start), reminderStartOfWeek(d)) / 7;
        if (weeks % interval !== 0) return false;
      }
    }
    return true;
  }
  if (type === 'interval') {
    if (!cfg.startDate || !cfg.intervalDays) return false;
    const start = new Date(cfg.startDate + 'T00:00:00');
    const diff = reminderDaysBetween(start, d);
    return diff >= 0 && diff % cfg.intervalDays === 0;
  }
  if (type === 'monthly') {
    if (!cfg.startDate) return false;
    const start = new Date(cfg.startDate + 'T00:00:00');
    if (d < start) return false;
    const interval = cfg.monthInterval || 1;
    if (interval > 1) {
      const monthsDiff = (d.getFullYear() - start.getFullYear()) * 12 + (d.getMonth() - start.getMonth());
      if (monthsDiff % interval !== 0) return false;
    }
    if (cfg.monthlyMode === 'nthWeekday') {
      const target = reminderNthWeekdayOfMonth(d.getFullYear(), d.getMonth(), cfg.nthWeekday, cfg.nthWeek);
      return !!target && target.getDate() === d.getDate();
    }
    return d.getDate() === cfg.dayOfMonth;
  }
  if (type === 'yearly') {
    if (!cfg.startDate) return false;
    const start = new Date(cfg.startDate + 'T00:00:00');
    if (d < start) return false;
    if (d.getMonth() + 1 !== cfg.yearlyMonth) return false;
    const interval = cfg.yearInterval || 1;
    if (interval > 1) {
      const yearsDiff = d.getFullYear() - start.getFullYear();
      if (yearsDiff % interval !== 0) return false;
    }
    if (cfg.yearlyMode === 'nthWeekday') {
      const target = reminderNthWeekdayOfMonth(d.getFullYear(), d.getMonth(), cfg.yearlyNthWeekday, cfg.yearlyNthWeek);
      return !!target && target.getDate() === d.getDate();
    }
    return d.getDate() === cfg.yearlyDay;
  }
  return false;
}
function reminderOccursOnDate(reminder, dateStr) {
  const cfg = reminder.schedule_config || {};
  const d = new Date(dateStr + 'T00:00:00');
  if (!reminderMatchesPattern(reminder, d)) return false;
  const endType = cfg.endType || 'never';
  if (endType === 'onDate') {
    return !cfg.endDate || dateStr <= cfg.endDate;
  }
  if (endType === 'afterCount') {
    if (!cfg.endCount || !cfg.startDate) return true;
    const start = new Date(cfg.startDate + 'T00:00:00');
    let count = 0;
    for (let i = 0; i <= REMINDER_COUNT_SCAN_CAP_DAYS; i++) {
      const cur = new Date(start);
      cur.setDate(cur.getDate() + i);
      if (cur > d) break;
      if (reminderMatchesPattern(reminder, cur)) count++;
    }
    return count <= cfg.endCount;
  }
  return true;
}

// Next occurrence of a reminder on or after fromDateStr, searched day by day
// up to maxDays out (default 60 — generous enough for any interval reminder
// likely to be configured, without searching forever for a malformed one).
// Returns { dateStr, daysUntil } or null if nothing found in range.
function nextReminderOccurrence(reminder, fromDateStr, maxDays) {
  const from = new Date(fromDateStr + 'T00:00:00');
  for (let i = 0; i <= (maxDays || 60); i++) {
    const d = new Date(from);
    d.setDate(d.getDate() + i);
    const dateStr = `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
    if (reminderOccursOnDate(reminder, dateStr)) return { dateStr, daysUntil: i };
  }
  return null;
}

// Deep history: up to ~2 years of older events (older than the recent window). This
// is large and rarely changes, so it's fetched once at boot and refreshed only once
// per day. It lets the monthly calendar show events from months/years ago without
// re-pulling that whole range every few minutes.
async function fetchEventHistory() {
  const from = (()=>{ const d=new Date(); d.setDate(d.getDate()-730); return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`; })();
  const to   = (()=>{ const d=new Date(); d.setDate(d.getDate()-8);   return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`; })();
  try {
    const r = await fetch(`/api/events?from=${from}&to=${to}`);
    state.eventsHistory = await r.json();
  } catch { state.eventsHistory = state.eventsHistory || []; }
  mergeEvents();
}

// Combine the two windows into state.events (what the widgets render). De-dupe by a
// stable key in case the windows ever overlap at the boundary.
function mergeEvents() {
  const recent = state.eventsRecent || [];
  const history = state.eventsHistory || [];
  const seen = new Set();
  const keyOf = (e) => `${e.source||''}:${e.id}:${e.date}`;
  const merged = [];
  for (const e of [...history, ...recent]) {
    const k = keyOf(e);
    if (seen.has(k)) continue;
    seen.add(k); merged.push(e);
  }
  state.events = merged;
}

async function fetchWeather() {
  // Build the set of locations to fetch: the global default, plus any weather widget
  // that overrides its location (e.g. a vacation-house display). Each unique lat/lon
  // is fetched once and cached by key so multiple widgets at the same place share.
  state.weatherByLoc = state.weatherByLoc || {};
  const locations = new Map(); // key -> {lat, lon}
  const { weather_lat: gLat, weather_lon: gLon } = state.settings || {};
  if (gLat && gLon) locations.set(`${gLat},${gLon}`, { lat: gLat, lon: gLon });

  (state.layout || []).forEach(w => {
    if (w.type && w.type.toLowerCase().startsWith('weather') && w.wxLat && w.wxLon) {
      locations.set(`${w.wxLat},${w.wxLon}`, { lat: w.wxLat, lon: w.wxLon });
    }
  });

  await Promise.all([...locations.entries()].map(async ([key, loc]) => {
    try {
      const r = await fetch(`/api/weather?lat=${encodeURIComponent(loc.lat)}&lon=${encodeURIComponent(loc.lon)}`);
      state.weatherByLoc[key] = await r.json();
    } catch {}
  }));

  // Keep state.weather as the global default for widgets without an override.
  if (gLat && gLon) state.weather = state.weatherByLoc[`${gLat},${gLon}`] || state.weather;
}

// Returns the weather object a given widget should render: its own location if it
// overrides, else the global default.
function weatherForWidget(widget) {
  if (widget && widget.wxLat && widget.wxLon) {
    return (state.weatherByLoc || {})[`${widget.wxLat},${widget.wxLon}`] || null;
  }
  return state.weather || null;
}

// Which display profile this screen shows. Resolution order:
//   1. An explicit ?display= in the URL always wins (manual override / old bookmarks).
//   2. Otherwise, the profile the app assigned to THIS screen (by device id).
//   3. Otherwise, the server's default display.
// This lets the app push a profile to a specific screen without editing any URL.
const URL_DISPLAY_SLUG = new URLSearchParams(window.location.search).get('display') || '';
// Preview mode: opened to *look at* a profile (e.g. on a phone) rather than running
// on the real wall display. We AUTO-DETECT this so it works even at the bare display
// URL without needing a ?preview=1 flag: a real wall display runs full-screen at the
// TV's native resolution (≥1920px wide in kiosk), whereas a phone browser has a much
// smaller viewport. Any viewport narrower/shorter than a TV is treated as a preview.
// Explicit overrides: ?preview=1 forces it on, ?preview=0 / ?nopreview forces it off.
const _previewParam = new URLSearchParams(window.location.search).get('preview');
const _noPreview = new URLSearchParams(window.location.search).get('nopreview') !== null;
// Independent of preview detection itself — a preview normally can't be
// directly edited (see wireDirectEditMode()'s own IS_PREVIEW check), since
// most preview contexts (a phone glancing at how a layout looks) shouldn't
// risk an accidental drag. The Layout tab's own Live Edit panel in app.html
// is the one deliberate exception: it explicitly WANTS editing available
// inside its accurately-rendered preview, so it opts in with this separate
// flag rather than the blanket ?preview=1 losing its other meaning
// (resolution override, avoiding screen-identity registration — both still
// apply normally even with editing allowed).
const ALLOW_EDIT_IN_PREVIEW = new URLSearchParams(window.location.search).get('allowEdit') === '1';
// Distinguishes the Layout tab's own small, read-only embedded thumbnail
// from "Open to Edit in New Tab" — both currently carry allowEdit=1 in
// their URL (a real, pre-existing bug in app.html's buildPreviewUrl(),
// found from a live incident: a schedule rule firing inside that supposedly
// glance-only thumbnail), so ALLOW_EDIT_IN_PREVIEW alone can't tell them
// apart. This is a SEPARATE, dedicated flag rather than changing what
// allowEdit=1 means — that flag also gates the beta.23 identity-separation
// fix (the dedicated preview_<slug> screen identity), which is correct and
// necessary for BOTH contexts equally, since both are previewing a real,
// named display rather than a screen's own disposable profile. Widening or
// narrowing THAT flag here would have been the wrong fix.
const EMBEDDED_THUMBNAIL = new URLSearchParams(window.location.search).get('embedded') === '1';
if (ALLOW_EDIT_IN_PREVIEW) {
  // See #back-to-app-link's own markup comment for the full reasoning —
  // this link exists specifically because this context (the app's "Open
  // to Edit in New Tab") had no way back to the app at all otherwise.
  try {
    const link = document.getElementById('back-to-app-link');
    if (link) link.style.display = 'block';
  } catch {}
}
// Windows full-screen kiosk only: launcher.vbs opens the wall display with
// ?kiosk=1. A Chromium --kiosk window has no chrome, no tab bar, and Alt+F4
// is easy to miss / disabled on some touchscreens — so reveal a small "Exit
// full-screen" button in the same tap-to-reveal cluster as the pencil. It
// closes the kiosk browser via POST /api/kiosk/exit (Windows-only +
// localhost-only, kills the chrome/msedge process using the kiosk-profile).
// window.close() is tried first but almost always no-ops for a URL the user
// didn't script-open, hence the server-side fallback.
const KIOSK_EXIT = new URLSearchParams(window.location.search).get('kiosk') === '1';
if (KIOSK_EXIT) {
  try {
    const btn = document.getElementById('kiosk-exit-btn');
    if (btn) {
      btn.style.display = '';
      btn.addEventListener('click', () => {
        btn.textContent = 'Exiting…';
        btn.disabled = true;
        try { window.close(); } catch {}
        fetch('/api/kiosk/exit', { method: 'POST' }).catch(() => {});
      });
    }
  } catch {}
}
function detectPreview() {
  if (_previewParam === '1') return true;
  // No more auto-detection from viewport size — that heuristic
  // (Math.max(vw, vh) < 1100) misidentified real displays as
  // phone/tablet previews on screens with unusual OS-level display scaling
  // (window.innerWidth/innerHeight are CSS pixels, not physical ones, so a
  // scaled screen can report a viewport far smaller than its real size).
  // Preview mode is now ONLY entered via an explicit ?preview=1 — which is
  // exactly what the real Live Preview iframe in app.html already sends
  // (see openLivePreviewSrc() / the "Open in a new tab" link), so this
  // doesn't affect that legitimate use. Everything else defaults to being
  // treated as a real display.
  return false;
}
let IS_PREVIEW = detectPreview();
if (IS_PREVIEW) {
  try {
    document.body.classList.add('preview');
    document.documentElement.classList.add('preview');
    // Distinguishes the "Open to Edit in New Tab" link (full-size, fully
    // interactive) from the Layout tab's own small read-only embedded
    // thumbnail preview (same 'preview' class) — a few things should behave
    // differently between "a live, editable stand-in for the real display"
    // and "a tiny non-interactive thumbnail," and blanket-treating both the
    // same was a real mistake (see #floating-switcher's own CSS comment for
    // the specific bug this caused). Checks EMBEDDED_THUMBNAIL specifically,
    // not just ALLOW_EDIT_IN_PREVIEW — both URLs actually carry allowEdit=1
    // (a separate, real bug in app.html's buildPreviewUrl(), found from a
    // live incident), so ALLOW_EDIT_IN_PREVIEW alone was never sufficient to
    // tell these two contexts apart to begin with.
    if (ALLOW_EDIT_IN_PREVIEW && !EMBEDDED_THUMBNAIL) document.body.classList.add('preview-editable');
  } catch {}
}
// The viewport-size heuristic above can't tell a genuinely small device apart
// from a real display whose CSS viewport is shrunk by unusual OS-level
// display scaling (confirmed case: a touchscreen reporting ~220% scaling
// despite showing "100%" in its own display settings, which shrank
// window.innerWidth well under the 1100px threshold). Multiplying by
// devicePixelRatio to "correct" for this was considered and rejected — real
// phones have high devicePixelRatio BY DESIGN (2-3x for retina displays), so
// that would misclassify actual phones as real displays and break Live
// Preview detection broadly. Instead: a per-device Settings toggle
// (force_real_display) that a person can flip once, after confirming their
// specific screen is being misdetected, rather than trying to guess it
// automatically. Only overrides the AUTO path — an explicit ?preview= URL
// param always wins, since that's someone deliberately asking to test one
// mode or the other regardless of what any device setting says.
function applyForceRealDisplayOverride() {
  if (_previewParam !== null) return; // explicit URL override always wins
  if (IS_PREVIEW && state.settings && state.settings.force_real_display === '1') {
    IS_PREVIEW = false;
    try {
      document.body.classList.remove('preview');
      document.documentElement.classList.remove('preview');
    } catch {}
  }
}
let DISPLAY_SLUG = URL_DISPLAY_SLUG; // may be replaced at boot by the assigned profile

// A stable per-device id. The CANONICAL id is persisted on the Pi (server-side)
// and adopted at boot via /api/screen-config, so the same physical screen is
// recognized across browser-cache wipes, kiosk URL changes, and app updates. We
// seed from localStorage for the very first request, then reconcile to the
// server's canonical id (and cache that) the moment we learn it.
let SCREEN_ID = (() => {
  // In the "Open to Edit in New Tab" context specifically, never touch or
  // read the shared 'screen-device-id' localStorage key at all — that's
  // exactly what a real kiosk display on the SAME browser/device already
  // uses for its OWN identity, and reading it here would silently register
  // this preview session AS that same real screen. Confirmed as a real,
  // reproducible incident, not a hypothetical: opening this from the same
  // browser as the host's own kiosk display silently applied a setting
  // change to that live, deployed screen with no warning at all. Derived
  // from the display slug being edited (not random) so reopening this same
  // preview for the same layout is consistent across sessions, while never
  // being able to collide with a real screen's own randomly-generated
  // 'scr_...' id — the 'preview_' prefix alone guarantees that.
  if (ALLOW_EDIT_IN_PREVIEW) {
    return 'preview_' + (URL_DISPLAY_SLUG || 'unknown').replace(/[^a-zA-Z0-9_-]/g, '_');
  }
  try {
    let id = localStorage.getItem('screen-device-id');
    if (!id) {
      id = 'scr_' + Math.random().toString(36).slice(2, 10) + Date.now().toString(36).slice(-4);
      localStorage.setItem('screen-device-id', id);
    }
    return id;
  } catch {
    return 'scr_ephemeral_' + Math.random().toString(36).slice(2, 10);
  }
})();
// Adopt the Pi's canonical id; call before opening the live SSE connection.
function adoptCanonicalScreenId(canonicalId) {
  // Never adopt the host's own canonical identity — not even in memory —
  // while in the "Open to Edit in New Tab" context (ALLOW_EDIT_IN_PREVIEW).
  // This used to only guard the localStorage WRITE below, on the reasoning
  // that SCREEN_ID still needed updating in memory "so preview requests are
  // internally consistent" — but every API call this session makes (fetching
  // and SAVING screen-level settings like the floating switcher) uses
  // SCREEN_ID directly, so that in-memory-only exception was exactly what
  // let a preview session silently adopt a real, deployed screen's identity
  // and modify its live settings. Confirmed as a real incident, not a
  // hypothetical. See SCREEN_ID's own declaration for the dedicated,
  // never-colliding identity this context uses instead.
  if (ALLOW_EDIT_IN_PREVIEW) return;
  // Still skipped for the small embedded thumbnail preview (Layout tab's
  // own Live Preview) for the same underlying reason, just scoped to
  // persistence only there — that context's SCREEN_ID is the ordinary
  // shared one (not the dedicated preview_* identity above, since it never
  // saves anything of its own), so only the localStorage write needs
  // guarding, not the in-memory value.
  if (canonicalId && canonicalId !== SCREEN_ID) {
    SCREEN_ID = canonicalId;
    if (!IS_PREVIEW) {
      try { localStorage.setItem('screen-device-id', canonicalId); } catch {}
    }
  }
}

// Restore blank-mode as early as possible (before first paint of the dashboard)
// so a refresh while blanked doesn't briefly flash the full screen. The keydown
// handler and persistence are wired later in init().
//
// DISABLED — the Tab-key screensaver feature isn't used; commented out rather
// than removed in case it's wanted again later. Left disabled here too (not
// just the keydown listener below) so a display that was ever blanked before
// this was turned off can't get permanently stuck that way with no key
// listener left to undo it.
const BLANK_KEY = 'blanked:' + (DISPLAY_SLUG || 'default');
// try { if (localStorage.getItem(BLANK_KEY) === '1') document.body.classList.add('blanked'); } catch {}

function withDisplayParam(url) {
  const sep0 = url.includes('?') ? '&' : '?';
  // Always include the screen id so the server can target live commands here and
  // track online status; include the display slug only when one is set.
  let out = `${url}${sep0}screen=${encodeURIComponent(SCREEN_ID)}`;
  if (DISPLAY_SLUG) out += `&display=${encodeURIComponent(DISPLAY_SLUG)}`;
  return out;
}

// On boot, ask the server which profile this screen is assigned (unless the URL
// already forced one). Sets DISPLAY_SLUG before any layout is fetched.
// Fetches this display's layout fresh from the server and applies it — either as
// the normal widget layout, or re-synthesized as ambient mode on top if that's
// currently active. Centralizing this (rather than each call site doing
// fetchLayout()+renderLayout() directly) exists specifically to prevent the bug
// class this session kept finding in different places: a raw fetchLayout() call
// overwrites state.layout with the real, non-ambient widgets, and forgetting to
// re-apply ambient mode afterward silently reverts a display sitting in Photo
// mode back to normal widgets.
// Every widget-data fetch that isn't tied to a specific widget instance —
// most either pull a global default (e.g. fetchWeather() always fetches
// the configured default location regardless of what's on screen right
// now) or no-op harmlessly if nothing on the CURRENT layout needs them.
// Extracted into its own function so both the 'layout' SSE handler below
// and the Layout Switcher's background pre-fetch (see prefetchSwitcherPresets())
// call the exact same set rather than maintaining two copies that could
// drift out of sync with each other.
async function fetchAllWidgetDataSet() {
  await Promise.allSettled([
    fetchWeather(), fetchTasksForLayout(), fetchTodoForLayout(), fetchShoppingListForLayout(),
    fetchNews(), fetchStocks(), fetchChoreChart(), fetchStickersForLayout(), fetchAirQuality(), fetchTravelTimes(),
    fetchOnThisDay(), fetchDailyQuote(), fetchSports(), fetchMetarTaf(),
  ]);
}

